-- Independent adults and tenants; never sends a real notification.
reset role;
update messaging.configuration set enabled=true,sending_enabled=true,requests_enabled=true,pilot_player_ids='{}';
insert into auth.users(id,email) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'group-'||n||'@test.test' from generate_series(51,56)n;
insert into auth.sessions(id,user_id) select ('10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid from generate_series(51,56)n;
insert into public.players(id,email,name) select n,'group-'||n||'@test.test','Group player '||n from generate_series(51,56)n;
insert into public.player_profile_details select n,date '1990-01-01' from generate_series(51,56)n;
insert into public.player_push_tokens(email,token) select 'group-'||n||'@test.test','ExponentPushToken[group-'||n||']' from generate_series(51,56)n;
set local role authenticated;
select pg_temp.login(51);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(52);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(53);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(54);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(55);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(56);select public.messaging_api('accept_rules','{"version":"2026-11-05"}');
select pg_temp.login(51);
select public.messaging_api('group_create','{"playerIds":[52,53],"title":"Weekend padel","body":"Shall we play?","clientId":"50000000-0000-0000-0000-000000000001"}')->>'id' as group_id \gset
select pg_temp.expect(public.messaging_api('group_create','{"playerIds":[53,52],"title":"Weekend padel","body":"Shall we play?","clientId":"50000000-0000-0000-0000-000000000001"}')->>'id'=:'group_id','group creation retries are idempotent');
reset role;
update messaging.configuration set groups_enabled=false;
set local role authenticated;
select pg_temp.expect(not (public.messaging_api('status')->>'groupsEnabled')::boolean,'group rollback switch hides client entry points');
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'group_id')),'unavailable');
select pg_temp.reject($q$select public.messaging_api('group_players','{"query":"Group"}')$q$,'unavailable');
reset role;
update messaging.configuration set groups_enabled=true;
set local role authenticated;
select pg_temp.reject($q$select public.messaging_api('group_create','{"playerIds":[52,54],"title":"Weekend padel","body":"Shall we play?","clientId":"50000000-0000-0000-0000-000000000001"}')$q$,'different audience');
select pg_temp.login(54);
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'group_id')),'unavailable');
reset role;
select id as invite_job from messaging.deliveries where conversation_id=:'group_id'::uuid and user_id='00000000-0000-0000-0000-000000000053' limit 1 \gset
update messaging.deliveries set state='leased',lease_id='60000000-0000-0000-0000-000000000001' where id=:'invite_job'::uuid;
select set_config('request.jwt.claims','{}',true);
set local role service_role;
select messaging.delivery_api('context',jsonb_build_object('id',:'invite_job','lease','60000000-0000-0000-0000-000000000001')) as invite_context \gset
reset role;
select pg_temp.expect(:'invite_context'::jsonb->>'title'='4M Padel','private group title stays out of push payload');
select pg_temp.expect(:'invite_context'::jsonb->>'path'='/messages/'||:'group_id','group invitation push has its exact chat route');
select pg_temp.expect(not (:'invite_context'::jsonb::text like '%Shall we play%'),'group introduction stays out of push payload');
set local role authenticated;
select pg_temp.login(52);
select pg_temp.expect(public.messaging_api('read',jsonb_build_object('conversationId',:'group_id'))->'conversation'->>'state'='pending','group invitation requires acceptance');
select pg_temp.expect(jsonb_array_length(public.messaging_api('group_members',jsonb_build_object('conversationId',:'group_id')))=2,'unaccepted players do not see other invitees');
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','Not accepted','clientId',gen_random_uuid())),'cannot send');
select pg_temp.expect(not messaging.realtime_can_read('messaging-thread:'||:'group_id'),'invited members cannot subscribe to group traffic');
select pg_temp.reject(format('select public.messaging_api(''respond'',%L)',jsonb_build_object('conversationId',:'group_id','response','accept')),'Update the app');
select public.messaging_api('respond',jsonb_build_object('conversationId',:'group_id','response','accept','groupsVersion','1'));
select pg_temp.expect(messaging.realtime_can_read('messaging-thread:'||:'group_id'),'accepted members can subscribe');
select public.messaging_api('send',jsonb_build_object('conversationId',:'group_id','body','Accepted member message','clientId',gen_random_uuid()));
-- Public event cards are previews, never a membership or publication bypass.
reset role;
update public.calendar set venue='Test courts',city='Test city',poster_image_url='https://example.test/poster.jpg',sapa_status='Gold' where id=100;
set local role authenticated;
select public.messaging_api('send',jsonb_build_object('conversationId',:'group_id','body','','eventId',100,'clientId','50000000-0000-0000-0000-000000000020')) as shared_event \gset
select pg_temp.expect(:'shared_event'::jsonb->'card'->>'poster'='https://example.test/poster.jpg' and :'shared_event'::jsonb->'card'->>'venue'='Test courts','event-card preview comes from canonical published event details');
select pg_temp.expect(:'shared_event'::jsonb->'card'->>'title'='4M Open','accepted member can attach a published event without body text');
select pg_temp.expect(public.messaging_api('send',jsonb_build_object('conversationId',:'group_id','body','','eventId',100,'clientId','50000000-0000-0000-0000-000000000020'))->>'id'=:'shared_event'::jsonb->>'id','event-card retry returns same message');
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','','eventId',200,'clientId','50000000-0000-0000-0000-000000000020')),'different content');
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','','clientId',gen_random_uuid())),'Write a message');
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','','eventId',100,'cardTab','Admin','clientId',gen_random_uuid())),'published');
reset role;
update public.calendar set is_visible=false where id=100;
set local role authenticated;
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','See this event','eventId',100,'clientId',gen_random_uuid())),'published');
select pg_temp.expect((public.messaging_api('read',jsonb_build_object('conversationId',:'group_id'))->'messages' @> jsonb_build_array(jsonb_build_object('id',:'shared_event'::jsonb->>'id','card',null))),'unpublishing removes card metadata from existing group messages');
reset role;
update public.calendar set is_visible=true,sanction_status='rejected' where id=100;
set local role authenticated;
select pg_temp.reject(format('select public.messaging_api(''send'',%L)',jsonb_build_object('conversationId',:'group_id','body','','eventId',100,'clientId',gen_random_uuid())),'published');
reset role;
update public.calendar set sanction_status=null where id=100;
set local role authenticated;
select pg_temp.login(53);
select pg_temp.expect(jsonb_array_length(public.messaging_api('read',jsonb_build_object('conversationId',:'group_id'))->'messages')=1,'invitation reveals introduction only');
select public.messaging_api('respond',jsonb_build_object('conversationId',:'group_id','response','accept','groupsVersion','1'));
select pg_temp.expect(jsonb_array_length(public.messaging_api('read',jsonb_build_object('conversationId',:'group_id'))->'messages')=1,'joining does not reveal earlier discussion');
select public.messaging_api('group_leave',jsonb_build_object('conversationId',:'group_id'));
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'group_id')),'unavailable');
reset role;
insert into public.event_registrations(event_id,email,payment_status) values(1000,'group-52@test.test','paid'),(1000,'group-55@test.test','paid'),(2000,'group-56@test.test','paid');
update public.organisations set name=case when created_by=9 then 'Organisation A' else 'Organisation B' end;
set local role authenticated;
select pg_temp.login(9);
select pg_temp.reject($q$select public.messaging_api('admin_scopes')$q$,'two-factor');
select pg_temp.login(9,'aal2');
select pg_temp.expect(jsonb_array_length(public.messaging_api('admin_inbox','{"scope":"org:30000000-0000-0000-0000-000000000001"}'))=0,'opening admin player messaging loads an empty authorised inbox');
select pg_temp.expect(jsonb_array_length(public.messaging_api('admin_players','{"scope":"org:30000000-0000-0000-0000-000000000001","query":"Group player"}'))=2,'admin search returns its own eligible players only');
select pg_temp.reject($q$select public.messaging_api('admin_players','{"scope":"org:30000000-0000-0000-0000-000000000002","query":"Group"}')$q$,'access denied');
select pg_temp.reject($q$select public.messaging_api('admin_send','{"scope":"org:30000000-0000-0000-0000-000000000001","playerIds":[55,56],"body":"Private update","clientId":"50000000-0000-0000-0000-000000000002"}')$q$,'unavailable');
select public.messaging_api('admin_send','{"scope":"org:30000000-0000-0000-0000-000000000001","playerIds":[52,55],"body":"Private update","clientId":"50000000-0000-0000-0000-000000000002"}') as admin_sent \gset
select pg_temp.expect(jsonb_array_length(:'admin_sent'::jsonb)=2,'private batch creates separate conversations');
select pg_temp.expect(public.messaging_api('admin_send','{"scope":"org:30000000-0000-0000-0000-000000000001","playerIds":[55,52],"body":"Private update","clientId":"50000000-0000-0000-0000-000000000002"}')=:'admin_sent'::jsonb,'admin retries do not duplicate messages');
select public.messaging_api('admin_send','{"scope":"org:30000000-0000-0000-0000-000000000001","mode":"group","title":"Practice squad","playerIds":[52,55],"body":"Our squad chat","clientId":"50000000-0000-0000-0000-000000000003"}')->0->>'id' as admin_group \gset
select pg_temp.expect(jsonb_array_length(public.messaging_api('admin_inbox','{"scope":"org:30000000-0000-0000-0000-000000000001"}'))=3,'admin inbox loads only its own scoped private and group conversations');
select pg_temp.login(10,'aal2');
select pg_temp.reject($q$select public.messaging_api('admin_inbox','{"scope":"org:30000000-0000-0000-0000-000000000001"}')$q$,'access denied');
select pg_temp.expect(jsonb_array_length(public.messaging_api('admin_inbox','{"scope":"org:30000000-0000-0000-0000-000000000002"}'))=0,'another organisation has a separate empty admin inbox');
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'admin_group')),'unavailable');
select pg_temp.login(11,'aal2');
select pg_temp.expect(jsonb_array_length(public.messaging_api('admin_scopes'))=0,'a broad sidebar tab cannot select another organisation');
select pg_temp.login(55);
select public.messaging_api('respond',jsonb_build_object('conversationId',:'admin_sent'::jsonb->1->>'id','response','accept','groupsVersion','1'));
select pg_temp.expect(public.messaging_api('read',jsonb_build_object('conversationId',:'admin_sent'::jsonb->1->>'id'))->'messages'->0->'sender'->>'role'='admin','official admin message role is server-derived');
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'admin_sent'::jsonb->0->>'id')),'unavailable');
reset role;
update public.organisations set created_by=null where created_by=9;
delete from public.organisation_members where user_email='org-a@test.test';
set local role authenticated;
select pg_temp.login(9,'aal2');
select pg_temp.reject(format('select public.messaging_api(''read'',%L)',jsonb_build_object('conversationId',:'admin_group')),'unavailable');
reset role;
update public.organisations set created_by=9 where id='30000000-0000-0000-0000-000000000001';
insert into public.organisation_members values('30000000-0000-0000-0000-000000000001','org-a@test.test','owner');
-- Opt-outs, blocks and retry payloads are checked on the server too.
insert into messaging.blocks(user_id,blocked_id) values('00000000-0000-0000-0000-000000000052','00000000-0000-0000-0000-000000000054');
update messaging.accounts set allow_requests=false where player_id=56;
set local role authenticated;
select pg_temp.login(51);
select pg_temp.reject($q$select public.messaging_api('group_create','{"playerIds":[52,54],"title":"Blocked pair","body":"Join us","clientId":"50000000-0000-0000-0000-000000000004"}')$q$,'cannot be created');
select pg_temp.reject($q$select public.messaging_api('group_create','{"playerIds":[52,56],"title":"Opted out","body":"Join us","clientId":"50000000-0000-0000-0000-000000000005"}')$q$,'unavailable');
select pg_temp.expect(not exists(select 1 from jsonb_array_elements(public.messaging_api('group_players','{"query":"Group player"}')) item where item->>'id' in ('51','56')),'group search excludes self and request opt-outs');
reset role;
delete from messaging.blocks where user_id='00000000-0000-0000-0000-000000000052' and blocked_id='00000000-0000-0000-0000-000000000054';
update messaging.accounts set allow_requests=true where player_id=56;
